void xoacuoi(node **head){
    if(*head == NULL) return;          // rong
    if((*head)->next == NULL){         // 1 node
        free(*head); *head = NULL;
    } else {
        node *tmp = *head;
        while(tmp->next->next != NULL)
            tmp = tmp->next;           // toi node thu 2 tu cuoi
        node *delNode = tmp->next;
        tmp->next = NULL;
        free(delNode);
    }
}
